    company_website,
    service_to_pitch,
    session_id,
    user_name,
    timestamp: new Date().toISOString(),
    status: "processing"
  }
}];

const parsed = $("Input Parser").first().json;
const memoryData = $input.first().json;

const messages = memoryData.messages || [];
const memory = messages
  .map(msg => `${msg.role}: ${msg.content}`)
  .join("\n");

return [{
  json: {
    ...parsed,
    prior_memory: memory || "No prior memory found for this session.",
    has_memory: messages.length > 0
  }
}];

