const aggregateData = $("Parse Proposal Output").first().json;

const research = aggregateData.research || {};
const competitor = aggregateData.competitor || {};
const pricing = aggregateData.pricing || {};
const proposalOutput = aggregateData.proposal_output || {};
const proposalData = proposalOutput.proposal || {};

function cleanTemplateString(str) {
  if (!str || typeof str !== "string") return str;
  if (str.includes("{{ $json")) return "";
  return str;
}

function cleanArray(arr) {
  if (!Array.isArray(arr)) return arr;
  return arr.filter(item => {
    if (typeof item === "string" && item.includes("{{ $json")) return false;
    return item && item !== "";
  });
}

const actualWebsite = aggregateData.company_website || "";
const actualService = aggregateData.service_to_pitch || "";

const companyName = cleanTemplateString(research.company_name) || actualWebsite || "Unknown Company";
const industry = cleanTemplateString(research.industry) || "Not specified";
const website = cleanTemplateString(research.website) || actualWebsite || "";

return [{
  json: {
    overview: {
      companyName: companyName,
      industry: industry,
      website: website,
      summary: cleanTemplateString(proposalData.executive_summary) || "Analysis completed for " + companyName,
      keyInsights: cleanArray(research.recent_signals) || ["Company analysis completed"]
    },
    intelligence: {
      businessModel: cleanTemplateString(research.business_model) || "To be determined",
      targetAudience: cleanTemplateString(research.target_customers) || "To be determined",
      challenges: cleanArray(research.pain_points) || ["Analysis in progress"],
      opportunities: cleanArray(research.opportunities) || ["Opportunities identified"],
      techStack: cleanArray(research.technology_stack_hints) || ["Technology stack analysis pending"]
    },
    competitive: {
      competitors: (competitor.main_competitors && competitor.main_competitors.length > 0) ? competitor.main_competitors.map(c => ({
        name: cleanTemplateString(c.name) || "Competitor",
        strengths: [cleanTemplateString(c.how_to_differentiate) || "Differentiation strategy"],
        weaknesses: [cleanTemplateString(c.weakness) || "Competitive weakness"]
      })) : [{ name: "Market analysis", strengths: ["Competitive analysis"], weaknesses: ["In progress"] }],
      marketPosition: cleanTemplateString(competitor.positioning_angle) || "Strategic positioning defined",
      differentiators: cleanArray(competitor.unique_value_props) || ["Unique value propositions identified"]
    },
    pricing: {
      recommendedTier: cleanTemplateString(pricing.recommended_tier) || "Growth",
      tiers: (pricing.tiers && pricing.tiers.length > 0) ? pricing.tiers.map(t => ({
        name: cleanTemplateString(t.name) || "Tier",
        price: cleanTemplateString(t.price_range) || "Custom pricing",
        features: cleanArray(t.deliverables) || ["Features included"]
      })) : [
        { name: "Starter", price: "Contact for pricing", features: ["Basic features"] },
        { name: "Growth", price: "Contact for pricing", features: ["Advanced features"] },
        { name: "Enterprise", price: "Contact for pricing", features: ["Full features"] }
      ],
      justification: cleanTemplateString(pricing.justification) || "Pricing tailored to company needs"
    },
    proposal: {
      outreachEmail: cleanTemplateString(proposalOutput.outreach_email) || "Personalized outreach email generated",
      fullProposal: JSON.stringify(proposalData, null, 2),
      callToAction: cleanTemplateString(proposalData.call_to_action) || "Contact us to discuss how we can help your business grow."
    }
  }
}];

const sessionId = $("Input Parser").first().json.session_id;

if (!global.chatMemory) {
  global.chatMemory = {};
}

const sessionMemory = global.chatMemory[sessionId] || [];

return [{
  json: {
    session_id: sessionId,
    messages: sessionMemory,
    has_memory: sessionMemory.length > 0
  }
}];

const finalOutput = $input.first().json;
const inputData = $("Input Parser").first().json;
const sessionId = inputData.session_id;

if (!global.chatMemory) {
  global.chatMemory = {};
}

if (!global.chatMemory[sessionId]) {
  global.chatMemory[sessionId] = [];
}

global.chatMemory[sessionId].push({
  role: "user",
  content: inputData.company_website + " - " + inputData.service_to_pitch,
  timestamp: new Date().toISOString()
});

global.chatMemory[sessionId].push({
  role: "assistant",
  content: finalOutput.overview?.summary || "Analysis completed",
  timestamp: new Date().toISOString()
});

if (global.chatMemory[sessionId].length > 20) {
  global.chatMemory[sessionId] = global.chatMemory[sessionId].slice(-20);
}

return [{
  json: {
    success: true,
    session_id: sessionId,
    messages_stored: global.chatMemory[sessionId].length
  }
}];
